CREATE OR REPLACE FUNCTION public.auto_grade_mcq()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  total_auto INTEGER := 0;
  question_rec RECORD;
  student_answer TEXT;
BEGIN
  IF NEW.submission_type = 'mcq' AND NEW.mcq_answers IS NOT NULL THEN
    FOR question_rec IN
      SELECT id, correct_option, marks FROM assignment_questions
      WHERE assignment_id = NEW.assignment_id
    LOOP
      student_answer := NEW.mcq_answers->>(question_rec.id::TEXT);
      IF student_answer = question_rec.correct_option THEN
        total_auto := total_auto + question_rec.marks;
      END IF;
    END LOOP;
    NEW.auto_marks := total_auto;
    NEW.final_marks := total_auto;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_create_post(p_user_id uuid, p_category_key text, p_scope text, p_community_id uuid DEFAULT NULL::uuid, p_campus_id uuid DEFAULT NULL::uuid, p_college_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor TEXT;
        v_max   TEXT;
BEGIN
  IF p_user_id IS DISTINCT FROM auth.uid() OR auth.uid() IS NULL THEN RETURN FALSE; END IF;
  IF p_scope NOT IN ('campus', 'college_network', 'global') THEN RETURN FALSE; END IF;

  v_actor := public.user_admin_type(p_user_id, p_campus_id, p_college_id, p_community_id);

  IF v_actor = 'community_admin' AND p_community_id IS NULL THEN RETURN FALSE; END IF;
  IF p_community_id IS NOT NULL AND p_scope <> 'global' THEN RETURN FALSE; END IF;
  IF v_actor = 'campus_admin' AND p_campus_id IS NULL AND p_college_id IS NULL THEN RETURN FALSE; END IF;

  SELECT cp.max_scope INTO v_max
  FROM public.content_permissions cp
  JOIN public.content_categories cc ON cc.id = cp.category_id
  WHERE cp.actor_type = v_actor AND cc.key = p_category_key;

  RETURN v_max IS NOT NULL AND public.scope_level(v_max) >= public.scope_level(p_scope);
END;
$function$

CREATE OR REPLACE FUNCTION public.can_create_post_by_category(p_user_id uuid, p_category_id uuid, p_scope text, p_community_id uuid DEFAULT NULL::uuid, p_campus_id uuid DEFAULT NULL::uuid, p_college_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_key TEXT;
BEGIN
  IF p_user_id IS DISTINCT FROM auth.uid() OR auth.uid() IS NULL THEN RETURN FALSE; END IF;
  SELECT cc.key INTO v_key FROM public.content_categories cc WHERE cc.id = p_category_id;
  IF v_key IS NULL THEN RETURN FALSE; END IF;
  RETURN public.can_create_post(p_user_id, v_key, p_scope, p_community_id, p_campus_id, p_college_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.can_interact_post(p_post posts)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RETURN FALSE; END IF;
  IF NOT public.can_view_post(p_post) THEN RETURN FALSE; END IF;
  IF p_post.community_id IS NOT NULL THEN
    RETURN EXISTS (SELECT 1 FROM public.community_members
                   WHERE community_id = p_post.community_id AND user_id = v_uid);
  END IF;
  RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_interact_post_id(p_post_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p public.posts;
BEGIN
  SELECT * INTO p FROM public.posts WHERE id = p_post_id;
  RETURN p.id IS NOT NULL AND public.can_interact_post(p);
END;
$function$

CREATE OR REPLACE FUNCTION public.can_view_post(p_post posts)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid UUID := auth.uid();
        v_prof RECORD;
BEGIN
  IF v_uid IS NULL THEN RETURN FALSE; END IF;
  IF p_post.status = 'removed' THEN RETURN FALSE; END IF;

  -- Held (AI) posts: only author and moderators see them
  IF p_post.status = 'held' THEN
    RETURN p_post.author_id = v_uid
        OR public.has_mod_permission(v_uid, 'content.moderation', p_post.campus_id);
  END IF;

  IF p_post.scope = 'global' THEN RETURN TRUE; END IF;

  SELECT college_id, campus_id INTO v_prof FROM public.profiles WHERE id = v_uid;
  IF v_prof IS NULL THEN RETURN FALSE; END IF;

  IF p_post.scope = 'college_network' THEN
    RETURN v_prof.college_id IS NOT NULL AND v_prof.college_id = p_post.college_id;
  END IF;

  IF p_post.scope = 'campus' THEN
    RETURN v_prof.campus_id IS NOT NULL AND v_prof.campus_id = p_post.campus_id;
  END IF;

  RETURN FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_view_post_id(p_post_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p public.posts;
BEGIN
  SELECT * INTO p FROM public.posts WHERE id = p_post_id;
  RETURN p.id IS NOT NULL AND public.can_view_post(p);
END;
$function$

CREATE OR REPLACE FUNCTION public.has_mod_permission(p_user_id uuid, p_key text, p_campus_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_user_id IS DISTINCT FROM auth.uid() OR auth.uid() IS NULL THEN
    RETURN FALSE;
  END IF;
  IF EXISTS (SELECT 1 FROM public.admin_grants
             WHERE user_id = p_user_id AND admin_type = 'platform_admin') THEN
    RETURN TRUE;
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.moderation_permissions mp
    WHERE mp.user_id = p_user_id AND mp.permission_key = p_key
      AND (mp.scope = 'global'
           OR (p_campus_id IS NOT NULL AND mp.scope = 'campus' AND mp.campus_id = p_campus_id))
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_on_announcement()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  profile_rec RECORD;
BEGIN
  IF NEW.is_official = true THEN
    FOR profile_rec IN 
      SELECT id FROM profiles 
      WHERE (NEW.scope = 'global') 
         OR (NEW.scope = 'campus' AND campus_id = NEW.campus_id)
    LOOP
      IF profile_rec.id != NEW.author_id THEN
        PERFORM create_notification(
          profile_rec.id,
          'announcement',
          '📢 New official announcement posted',
          '/feed'
        );
      END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_on_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  faculty_name TEXT;
  student_rec RECORD;
BEGIN
  SELECT full_name INTO faculty_name FROM profiles WHERE id = NEW.posted_by;

  FOR student_rec IN
    SELECT id FROM profiles
    WHERE campus_id = NEW.campus_id
    AND department_id = NEW.department_id
    AND id != NEW.posted_by
    AND role = 'student'
  LOOP
    PERFORM create_notification(
      student_rec.id,
      'assignment',
      '📝 New assignment: ' || NEW.title || ' — ' || NEW.subject || ' (Due: ' || TO_CHAR(NEW.due_date, 'DD Mon') || ')',
      '/classroom/' || NEW.id::TEXT
    );
  END LOOP;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_on_comment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_author UUID;
BEGIN
  SELECT author_id INTO v_author FROM public.posts WHERE id = NEW.post_id;
  IF v_author IS NOT NULL AND v_author <> NEW.author_id THEN
    INSERT INTO public.notifications (recipient_id, actor_id, type, ref_type, ref_id, title, body)
    VALUES (v_author, NEW.author_id, 'post_comment', 'post', NEW.post_id,
            'New comment', left(NEW.body, 200));
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_on_like()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_author UUID;
BEGIN
  SELECT author_id INTO v_author FROM public.posts WHERE id = NEW.post_id;
  IF v_author IS NOT NULL AND v_author <> NEW.profile_id THEN
    INSERT INTO public.notifications (recipient_id, actor_id, type, ref_type, ref_id, title, body)
    VALUES (v_author, NEW.profile_id, 'post_reaction', 'post', NEW.post_id,
            'New like', 'Someone liked your post');
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_on_note()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  uploader_name TEXT;
  profile_rec RECORD;
BEGIN
  SELECT full_name INTO uploader_name FROM profiles WHERE id = NEW.uploaded_by;

  FOR profile_rec IN
    SELECT id FROM profiles
    WHERE campus_id = NEW.campus_id
    AND id != NEW.uploaded_by
  LOOP
    PERFORM create_notification(
      profile_rec.id,
      'note',
      uploader_name || ' uploaded a new note 📚',
      '/notes'
    );
  END LOOP;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.user_admin_type(p_user_id uuid, p_campus_id uuid DEFAULT NULL::uuid, p_college_id uuid DEFAULT NULL::uuid, p_community_id uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor TEXT;
BEGIN
  -- Identity guard: results are only ever meaningful for the caller.
  IF p_user_id IS DISTINCT FROM auth.uid() OR auth.uid() IS NULL THEN
    RETURN 'student';
  END IF;

  IF EXISTS (SELECT 1 FROM public.admin_grants
             WHERE user_id = p_user_id AND admin_type = 'platform_admin') THEN
    RETURN 'platform_admin';
  END IF;

  IF p_campus_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.admin_grants
    WHERE user_id = p_user_id AND admin_type = 'campus_admin' AND campus_id = p_campus_id) THEN
    RETURN 'campus_admin';
  END IF;

  IF p_college_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.admin_grants g
    JOIN public.campuses c ON c.college_id = p_college_id
    WHERE g.user_id = p_user_id AND g.admin_type = 'campus_admin'
      AND (g.campus_id = c.id OR (g.campus_id IS NULL AND g.college_id = p_college_id))) THEN
    RETURN 'campus_admin';
  END IF;

  IF p_community_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.admin_grants
    WHERE user_id = p_user_id AND admin_type = 'community_admin' AND community_id = p_community_id) THEN
    RETURN 'community_admin';
  END IF;

  RETURN 'student';
END;
$function$
